def compute(vars):
    revenue = vars["v1"]
    total_operating_revenues = vars["v2"]

    if total_operating_revenues == 0:
        return None

    ratio = revenue / total_operating_revenues
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
